using Marina.Domain.Catalog; using Marina.Domain.Commerce;
namespace Marina.Application.Commerce;
public sealed record CheckoutLine(Guid VariantId,int Quantity); public sealed record CheckoutCommand(Guid UserId,Guid AddressId,string IdempotencyKey,IReadOnlyCollection<CheckoutLine> Lines,string? CouponCode);
public interface ICommerceRepository { Task<Order?> FindOrderByIdempotencyAsync(Guid userId,string key,CancellationToken ct); Task<Address?> FindOwnedAddressAsync(Guid userId,Guid addressId,CancellationToken ct); Task<IReadOnlyDictionary<Guid,ProductVariant>> GetVariantsForCheckoutAsync(IEnumerable<Guid> ids,CancellationToken ct); Task<Coupon?> FindCouponAsync(string code,CancellationToken ct); Task<int> CouponUseCountAsync(Guid couponId,Guid? userId,CancellationToken ct); Task<T> InSerializableTransactionAsync<T>(Func<CancellationToken,Task<T>> operation,CancellationToken ct); void Add<T>(T entity)where T:class; Task ClearPurchasedCartAsync(Guid userId,IEnumerable<Guid> variantIds,CancellationToken ct); Task SaveAsync(CancellationToken ct); }
public sealed class CheckoutService(ICommerceRepository repository){public async Task<Order>CreateAsync(CheckoutCommand command,CancellationToken ct){if(string.IsNullOrWhiteSpace(command.IdempotencyKey)||command.IdempotencyKey.Length>100||command.Lines.Count==0||command.Lines.Any(x=>x.Quantity is<1 or>20)||command.Lines.Select(x=>x.VariantId).Distinct().Count()!=command.Lines.Count)throw new ArgumentException("Invalid checkout request.");var existing=await repository.FindOrderByIdempotencyAsync(command.UserId,command.IdempotencyKey,ct);if(existing is not null)return existing;return await repository.InSerializableTransactionAsync(async token=>{existing=await repository.FindOrderByIdempotencyAsync(command.UserId,command.IdempotencyKey,token);if(existing is not null)return existing;var address=await repository.FindOwnedAddressAsync(command.UserId,command.AddressId,token)??throw new KeyNotFoundException("Address not found.");var variants=await repository.GetVariantsForCheckoutAsync(command.Lines.Select(x=>x.VariantId),token);var order=new Order{UserId=command.UserId,AddressId=address.Id,IdempotencyKey=command.IdempotencyKey,PublicNumber=$"MAR-{DateTime.UtcNow:yyyy}-{Convert.ToHexString(Guid.NewGuid().ToByteArray())[..10]}",Status=OrderStatus.Confirmed,RecipientSnapshot=$"{address.Recipient}|{address.Phone}",AddressSnapshot=$"{address.Line1}|{address.City}|{address.PostalCode}"};foreach(var line in command.Lines){if(!variants.TryGetValue(line.VariantId,out var variant)||!variant.IsActive||variant.IsDeleted||!variant.Product.IsActive||variant.Product.IsDeleted)throw new KeyNotFoundException("Product variant unavailable.");var inventory=variant.Inventory??throw new InvalidOperationException("Product inventory is unavailable.");if(inventory.Quantity-inventory.ReservedQuantity<line.Quantity)throw new InvalidOperationException($"Insufficient inventory for {variant.Sku}.");var old=inventory.Quantity;inventory.Quantity-=line.Quantity;var translation=variant.Product.Translations.FirstOrDefault(x=>x.Culture=="en")??variant.Product.Translations.First();order.Items.Add(new OrderItem{VariantId=variant.Id,ProductName=translation.Name,Sku=variant.Sku,Color=variant.Color?.Translations.FirstOrDefault(x=>x.Culture=="en")?.Name,Size=variant.Size?.Translations.FirstOrDefault(x=>x.Culture=="en")?.Name,UnitPrice=variant.Price,Quantity=line.Quantity});order.Subtotal+=variant.Price*line.Quantity;repository.Add(new StockMovement{VariantId=variant.Id,Type=StockMovementType.Sale,OldQuantity=old,Delta=-line.Quantity,NewQuantity=inventory.Quantity,Reason="Order sale",ReferenceId=order.Id,ActorId=command.UserId});}if(!string.IsNullOrWhiteSpace(command.CouponCode)){var coupon=await repository.FindCouponAsync(command.CouponCode.Trim().ToUpperInvariant(),token)??throw new ArgumentException("Coupon is invalid.");var now=DateTime.UtcNow;if(!coupon.IsActive||now<coupon.ValidFromUtc||now>coupon.ValidToUtc||order.Subtotal<(coupon.MinimumPurchase??0))throw new ArgumentException("Coupon is invalid or expired.");var totalUses=await repository.CouponUseCountAsync(coupon.Id,null,token);var userUses=await repository.CouponUseCountAsync(coupon.Id,command.UserId,token);if((coupon.MaxUses.HasValue&&totalUses>=coupon.MaxUses)||(coupon.MaxUsesPerCustomer.HasValue&&userUses>=coupon.MaxUsesPerCustomer))throw new ArgumentException("Coupon usage limit reached.");order.CouponId=coupon.Id;order.Discount=coupon.Type==DiscountType.Percentage?order.Subtotal*coupon.Value/100:coupon.Value;if(coupon.MaximumDiscount.HasValue)order.Discount=Math.Min(order.Discount,coupon.MaximumDiscount.Value);order.Discount=Math.Min(order.Discount,order.Subtotal);repository.Add(new CouponUsage{CouponId=coupon.Id,UserId=command.UserId,OrderId=order.Id});}order.Shipping=order.Subtotal-order.Discount>=300?0:20;order.Tax=Math.Round((order.Subtotal-order.Discount+order.Shipping)*.15m,2);order.Total=order.Subtotal-order.Discount+order.Shipping+order.Tax;order.StatusHistory.Add(new OrderStatusHistory{Status=OrderStatus.Confirmed,ActorId=command.UserId,Reason="Order created"});repository.Add(order);repository.Add(new Payment{OrderId=order.Id,Provider="CashOnDelivery",Status=PaymentStatus.Pending,Amount=order.Total,Currency="SAR",IdempotencyKey="cod-"+order.Id.ToString("N")});await repository.SaveAsync(token);await repository.ClearPurchasedCartAsync(command.UserId,command.Lines.Select(x=>x.VariantId),token);return order;},ct);}}
